template:
enum Status {
    Active,
    Idle,
    Banned,
}

fn label(s: Status) -> &'static str {
    match s {
        Status::Active => "on",
        Status::Idle => "zzz",
        ⟦last_arm⟧ => "blocked",
    }
}

fn main() {
    println!("{} {} {}", label(Status::Active), label(Status::Idle), label(Status::Banned));
}
